function generateXunhuPayHash(data, appSecret) {
  const sortedKeys = Object.keys(data).sort();
  const stringA = sortedKeys.filter((key) => key !== "hash" && key !== "HASH" && data[key] !== "" && data[key] !== null).map((key) => `${key}=${data[key]}`).join("&");
  const stringSignTemp = stringA + appSecret;
  return md5(stringSignTemp);
}
__name(generateXunhuPayHash, "generateXunhuPayHash");
async function md5(str) {
  const encoder = new TextEncoder();
  const data = encoder.encode(str);
  const hashBuffer = await crypto.subtle.digest("MD5", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}
