async function saveStaticFile(env, path, content17) {
  const envType = detectEnvironment(env);
  const key = path.startsWith("/") ? path.slice(1) : path;
  try {
    if (envType === "production" && env.R2_BUCKET) {
      await env.R2_BUCKET.put(key, content17, {
        httpMetadata: {
          contentType: getContentType(key)
        },
        cacheControl: "public, max-age=86400"
      });
    } else if (env && env.KV) {
      const kvKey = `static:${key}`;
      await env.KV.put(kvKey, content17, {
        expirationTtl: 86400 * 30
        // 30 天过期
      });
    } else {
      console.error("[StaticStorage] No storage available");
      return false;
    }
    return true;
  } catch (error) {
    console.error("[StaticStorage] Save failed:", error);
    return false;
  }
}
