async function getUserFromToken(env, token) {
  const row = await env.DB.prepare(`
    SELECT u.id, u.email
    FROM users u
    INNER JOIN user_sessions s ON u.id = s.user_id
    WHERE s.token = ? AND s.expires_at > datetime('now')
  `).bind(token).first();
  return row || null;
}
